import{_ as r,o,c as e,ag as a}from"./chunks/framework.DXGyWiRo.js";const n="/images/youtube-university-cover.jpg",s="/images/youtube-roadmap.png",b=JSON.parse('{"title":"把 YouTube 当大学：四阶段 AI 自学路线图（工程师版）","description":"收藏夹里躺着几百小时的 AI 课程，越存越焦虑？这篇把 7 位顶级创作者的课排成一张四阶段路线图：直觉数学→系统理论→手写代码→论文前沿，附工程师版的压缩取舍和每阶段的过关标准。","frontmatter":{"title":"把 YouTube 当大学：四阶段 AI 自学路线图（工程师版）","date":"2026-10-22T00:00:00.000Z","category":"AI 实践","emoji":"🎓","description":"收藏夹里躺着几百小时的 AI 课程，越存越焦虑？这篇把 7 位顶级创作者的课排成一张四阶段路线图：直觉数学→系统理论→手写代码→论文前沿，附工程师版的压缩取舍和每阶段的过关标准。"},"headers":[],"relativePath":"posts/youtube-university.md","filePath":"posts/youtube-university.md"}'),i={name:"posts/youtube-university.md"};function l(d,t,g,u,p,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="把-youtube-当大学-四阶段-ai-自学路线图-工程师版" tabindex="-1">把 YouTube 当大学：四阶段 AI 自学路线图（工程师版） <a class="header-anchor" href="#把-youtube-当大学-四阶段-ai-自学路线图-工程师版" aria-label="Permalink to &quot;把 YouTube 当大学：四阶段 AI 自学路线图（工程师版）&quot;">​</a></h1><blockquote><p>2026-10-22 · 阅读约 6 分钟</p></blockquote><p><img src="'+n+'" alt="封面：沿着四级台阶往上走，每级一种学问"></p><p>学 AI 的人大概都有同一个收藏夹：几百小时的课程躺在里面，越存越焦虑。问题不在课不好，而在<strong>没有顺序</strong>——上来就啃论文的劝退，停在科普层的又永远入不了门。</p><p>我最近系统梳理了一批 YouTube 上最硬核的 AI 创作者，把他们的课排成了一张四阶段路线图。这篇你将获得：</p><ul><li>一张能直接照着走的<strong>四阶段路线图</strong>（直觉数学 → 系统理论 → 手写代码 → 论文前沿）；</li><li>每个阶段<strong>只看谁、看哪几集</strong>的最短路径，一共 7 位创作者；</li><li>一份<strong>工程师版的取舍</strong>：有编程和数学底子的人，哪些阶段该压缩、哪个阶段必须加重。</li></ul><p>先说我的立场：<strong>视频不是课，敲完的代码才是。</strong> 这条路线里只有第三阶段是「学」，其余三阶段都是为它做准备或做延伸。顺序反了，事倍功半。</p><p><img src="'+s+'" alt="四阶段路线图"></p><h2 id="阶段一-直觉与数学底座-1–2-周-只为建立画面感" tabindex="-1">阶段一：直觉与数学底座（1–2 周，只为建立画面感） <a class="header-anchor" href="#阶段一-直觉与数学底座-1–2-周-只为建立画面感" aria-label="Permalink to &quot;阶段一：直觉与数学底座（1–2 周，只为建立画面感）&quot;">​</a></h2><p><strong>看谁</strong>：3Blue1Brown 的《Neural Networks》系列，重点是最后两集《But what is a GPT?》和《Attention in transformers》；StatQuest 的 Transformer 图解，用来攻克 Q、K、V 矩阵相乘的恐惧。</p><p><strong>怎么学</strong>：这一阶段的目标是让「梯度下降」「反向传播」「注意力」在你脑子里变成画面，而不是公式。3Blue1Brown 的动画把损失函数画成曲面、把注意力画成信息流动，看完再推公式，难度直接减半。</p><p><strong>我的取舍</strong>：有高数和线代底子的工程师，这一阶段<strong>压缩到一周</strong>。不用从神经网络第一集慢慢看，直接跳 GPT 和 Attention 两集，StatQuest 当字典查——哪个概念卡住，查哪个。</p><h2 id="阶段二-系统理论-3–4-周-建立完整地图" tabindex="-1">阶段二：系统理论（3–4 周，建立完整地图） <a class="header-anchor" href="#阶段二-系统理论-3–4-周-建立完整地图" aria-label="Permalink to &quot;阶段二：系统理论（3–4 周，建立完整地图）&quot;">​</a></h2><p><strong>看谁</strong>：李宏毅。首选《生成式 AI 導論 2024》，再用他的 Machine Learning 课程补齐 CNN、GAN、强化学习这些拼图。</p><p><strong>怎么学</strong>：李宏毅的价值是「全貌」——Transformer 架构、Prompt 工程、RLHF/DPO 对齐、扩散模型的数学本质，一门课全讲清，而且用华语讲最难的概念，对国内学习者极其友好。这一阶段过完，你应该能对任何 AI 新闻说出它在地图上的位置。</p><p><strong>我的取舍</strong>：<strong>速通，不做题。</strong> 这一阶段是建立坐标系，不是考试；唯一要慢下来的是扩散模型那部分，数学本质讲透的课不多，他是其中之一。</p><h2 id="阶段三-手写代码-2–3-个月-全程的重心" tabindex="-1">阶段三：手写代码（2–3 个月，全程的重心） <a class="header-anchor" href="#阶段三-手写代码-2–3-个月-全程的重心" aria-label="Permalink to &quot;阶段三：手写代码（2–3 个月，全程的重心）&quot;">​</a></h2><p><strong>看谁</strong>：只有一个人，Andrej Karpathy 的《Neural Networks: Zero to Hero》。顺序不能乱：</p><ol><li><strong>micrograd</strong>：一百多行手写自动微分引擎，反向传播从此不是黑盒；</li><li><strong>makemore 系列</strong>：从 Bigram 字符模型一路搭到 MLP、BatchNorm、WaveNet；</li><li><strong>从零构建 GPT</strong>：逐行实现多头注意力、残差连接、自回归生成，即 nanoGPT；</li><li><strong>分词器</strong>：亲手复现 BPE / tiktoken 的逻辑；</li><li>最后看《Intro to Large Language Models》一小时综述收官。</li></ol><p><strong>怎么学</strong>：原指南里有一句我完全同意的话——<strong>严禁仅看视频，务必逐行敲代码跑通</strong>。这一阶段没有捷径，看懂和写出来之间隔着整个工程能力。</p><p><strong>我的取舍</strong>：<strong>加重，而且是我自己路线的锚。</strong> 我给自己排的 Agent 工程师学习路线就是以 Karpathy 为核心——先能从零复刻，再谈框架和应用。工程师转型 AI 最大的幻觉是「会调 API 就算入门」，这一阶段就是用来打破幻觉的。</p><h2 id="阶段四-论文与前沿-长期-当字典和雷达用" tabindex="-1">阶段四：论文与前沿（长期，当字典和雷达用） <a class="header-anchor" href="#阶段四-论文与前沿-长期-当字典和雷达用" aria-label="Permalink to &quot;阶段四：论文与前沿（长期，当字典和雷达用）&quot;">​</a></h2><p><strong>看谁</strong>：Yannic Kilcher 逐页带读顶会论文（《Attention Is All You Need》、GPT-3、LLaMA、DeepSeek 都拆过），他的特点是不只讲优点，还较真消融实验是否充分、复现难度多大；AI Explained 做各家大模型的同台横评，帮你辨别发布会 PPT 和真实能力；Two Minute Papers 每天 3–5 分钟看视觉/图形学突破，纯开眼界。</p><p><strong>我的取舍</strong>：<strong>按需查，不追更。</strong> 这一阶段是雷达不是课程：遇到读不懂的论文，先搜 Kilcher 有没有讲过；要选型，先看横评。把它当连续剧天天追，是这一阶段最大的时间陷阱。</p><h2 id="过关标准-这篇真正要你抄走的东西" tabindex="-1">过关标准（这篇真正要你抄走的东西） <a class="header-anchor" href="#过关标准-这篇真正要你抄走的东西" aria-label="Permalink to &quot;过关标准（这篇真正要你抄走的东西）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>看谁</th><th>过关标准</th></tr></thead><tbody><tr><td>一 · 直觉数学</td><td>3Blue1Brown / StatQuest</td><td>能对着白板讲清注意力在算什么</td></tr><tr><td>二 · 系统理论</td><td>李宏毅</td><td>任何 AI 新闻能定位它在全图的位置</td></tr><tr><td>三 · 手写代码</td><td>Karpathy</td><td>能默写 micrograd 的 backward、独立跑通 nanoGPT</td></tr><tr><td>四 · 论文前沿</td><td>Kilcher / AI Explained</td><td>能独立读完一篇论文并判断消融是否可信</td></tr></tbody></table><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>这张路线图里，真正决定你能不能入行的只有第三阶段，其余都是加速器或减速带。收藏这篇不算开始——把 micrograd 敲完，才算。</p><p>（原始整理来自我的一份 YouTube 学习资料调研文档，博主与系列均为公开信息；阶段划分与取舍是我按工程师背景做的调整。）</p>',29)])])}const m=r(i,[["render",l]]);export{b as __pageData,m as default};
